-- orders: 500.000 dòng, chỉ có PRIMARY KEY trên id
-- khách #1 có 61 đơn = 0.012% số dòng cả bảng

-- [A] chưa có index cho cột customer_id
EXPLAIN (ANALYZE, BUFFERS)
SELECT * FROM orders WHERE customer_id = 1;

-- [+] tạo index trên đúng cột đang lọc
CREATE INDEX idx_orders_customer ON orders(customer_id);
ANALYZE orders;

-- [B] chạy lại ĐÚNG câu đó, không sửa một chữ
EXPLAIN (ANALYZE, BUFFERS)
SELECT * FROM orders WHERE customer_id = 1;
